	desiredRefs map[plumbing.ReferenceName]planner.DesiredRef,
	batchableSource bool,
) (bool, string) {
	if !s.desiredTargetRefsAbsent(desiredRefs) {
		return false, ""
	}
	if batchableSource && s.hasBootstrapResumeMarker(desiredRefs) {
