// FetchPack fetches a packfile from source and returns the pack stream as a reader.
// Caller must close the returned ReadCloser.
func (s *RefService) FetchPack(
	ctx context.Context,
	conn Conn,
	desired map[plumbing.ReferenceName]DesiredRef,
	targetRefs map[plumbing.ReferenceName]plumbing.Hash,
) (io.ReadCloser, error) {
	switch s.Protocol {
	case "v2":
		return fetchPackV2(ctx, conn, s.V2Caps, desired, targetRefs, s.Verbose)
	case "v1":
		return fetchPackV1(ctx, conn, s.V1Adv, desired, targetRefs, s.Verbose)
	default:
		return nil, fmt.Errorf("unsupported source protocol %q", s.Protocol)
	}
}

// FetchCommitParents fetches a commit graph (v2 fetch with tree:0 filter) and
// extracts (commit -> parent hashes) directly from the pack stream
// without materializing the full object set into a store. Peak memory
// during this call is dominated by the result map plus a small fixed
// delta-resolution cache; no commit content is retained.
//
// Optional haves let the source skip commits already reachable from those
// hashes, which is valuable when planning later branches that share history
// with an already-planned trunk.
// Returns an empty map (not nil) when the source has no new commits.
func (s *RefService) FetchCommitParents(
	ctx context.Context,
	conn Conn,
	ref DesiredRef,
	haves []plumbing.Hash,
) (parents map[plumbing.Hash][]plumbing.Hash, err error) {
	if s.Protocol != "v2" {
		return nil, errors.New("commit parents fetch requires protocol v2")
	}
	if !s.V2Caps.FetchSupports("filter") {
		return nil, errors.New("source does not advertise fetch filter support")
	}

	sortedHaves := SortedUniqueHashes(haves)
	cmdArgs := make([]string, 0, 4+len(sortedHaves))
	cmdArgs = append(cmdArgs,
		"ofs-delta",
		"no-progress",
		"filter tree:0",
		"want "+ref.SourceHash.String(),
	)
	for _, h := range sortedHaves {
		cmdArgs = append(cmdArgs, "have "+h.String())
	}
	cmdArgs = append(cmdArgs, "done")

	body, err := EncodeCommand("fetch", s.V2Caps.RequestCapabilities(), cmdArgs)
	if err != nil {
		return nil, err
	}
	reader, err := PostRPCStream(ctx, conn, transport.UploadPackService, body, true, "upload-pack fetch")
	if err != nil {
		return nil, err
	}
	defer ioutil.CheckClose(reader, &err)

	parents = map[plumbing.Hash][]plumbing.Hash{}
	consumeErr := consumeV2FetchPack(reader, false, nil, func(packReader io.Reader) error {
		got, perr := ExtractCommitParents(packReader)
		if perr != nil {
			return perr
		}
		parents = got
		return nil
	})
	if consumeErr != nil {
		return nil, consumeErr
	}
	return parents, nil
}

// Capabilities returns the sorted capability list for display.
func (s *RefService) Capabilities() []string {
	switch s.Protocol {
	case "v2":
		return s.V2Caps.SortedKeys()
	case "v1":
		return AdvRefsCaps(s.V1Adv)
	default:
		return nil
	}
}

// --- V2 fetch implementation ---

func fetchToStoreV2(
	ctx context.Context,
	store storer.Storer,
	conn Conn,
	caps *V2Capabilities,
	desired map[plumbing.ReferenceName]DesiredRef,
	targetRefs map[plumbing.ReferenceName]plumbing.Hash,
	verbose bool,
) error {
	wants := collectWants(desired)
	haves := SortedUniqueHashes(refValues(targetRefs))
	if len(wants) == 0 {
		return git.NoErrAlreadyUpToDate
	}

	cmdArgs := make([]string, 0, len(wants)+len(haves)+4)
	// NOTE: no "thin-pack" argument. The relayed pack must stay
	// self-contained so callers (e.g. replicate) can forward it to
	// receive-pack servers that may advertise "no-thin". See
	// planner.SupportsReplicateRelay for the matching invariant.
	cmdArgs = append(cmdArgs, "ofs-delta")
	if !verbose {
		cmdArgs = append(cmdArgs, "no-progress")
	}
	for _, h := range wants {
		cmdArgs = append(cmdArgs, "want "+h.String())
	}
	for _, h := range haves {
		cmdArgs = append(cmdArgs, "have "+h.String())
	}
	cmdArgs = append(cmdArgs, "done")

	body, err := EncodeCommand("fetch", caps.RequestCapabilities(), cmdArgs)
	if err != nil {
		return err
	}
	reader, err := PostRPCStream(ctx, conn, transport.UploadPackService, body, true, "upload-pack fetch")
	if err != nil {
		return err
	}
	defer ioutil.CheckClose(reader, &err)
	return storeV2FetchPack(store, reader, verbose, conn.ProgressWriter())
}

func fetchPackV2(
	ctx context.Context,
	conn Conn,
	caps *V2Capabilities,
	desired map[plumbing.ReferenceName]DesiredRef,
	targetRefs map[plumbing.ReferenceName]plumbing.Hash,
	verbose bool,
) (io.ReadCloser, error) {
	wants := collectWants(desired)
	haves := SortedUniqueHashes(refValues(targetRefs))
	if len(wants) == 0 {
		return nil, git.NoErrAlreadyUpToDate
	}

	cmdArgs := make([]string, 0, len(wants)+len(haves)+4)
	// NOTE: no "thin-pack" argument. The relayed pack must stay
	// self-contained so callers (e.g. replicate) can forward it to
	// receive-pack servers that may advertise "no-thin". See
	// planner.SupportsReplicateRelay for the matching invariant.
	cmdArgs = append(cmdArgs, "ofs-delta")
	if !verbose {
		cmdArgs = append(cmdArgs, "no-progress")
	}
	// Only request include-tag if the server supports it (issue #6).
	if hasTag(desired) && caps.FetchSupports("include-tag") {
		cmdArgs = append(cmdArgs, "include-tag")
	}
	for _, h := range wants {
		cmdArgs = append(cmdArgs, "want "+h.String())
	}
	for _, h := range haves {
		cmdArgs = append(cmdArgs, "have "+h.String())
	}
	cmdArgs = append(cmdArgs, "done")

	body, err := EncodeCommand("fetch", caps.RequestCapabilities(), cmdArgs)
	if err != nil {
		return nil, err
	}
	reader, err := PostRPCStream(ctx, conn, transport.UploadPackService, body, true, "upload-pack fetch")
	if err != nil {
		return nil, err
	}
	packStream, err := openV2PackStream(reader, verbose, conn.ProgressWriter())
	if err != nil {
		_ = reader.Close()
		return nil, err
	}
	return packStream, nil
}

func storeV2FetchPack(store storer.Storer, r io.Reader, verbose bool, progressOut io.Writer) error {
	return consumeV2FetchPack(r, verbose, progressOut, func(packReader io.Reader) error {
		if err := packfile.UpdateObjectStorage(store, packReader); err != nil {

