// Probe: one-shot bootstrap resume under --best-effort where the branch create
// is individually rejected. Does the resume marker survive?
func TestProbeBestEffortRejectedCreateDropsMarker(t *testing.T) {
	sourceRepo, sourceFS := newSourceRepo(t)
	makeCommits(t, sourceRepo, sourceFS, 4)
	branchRef := plumbing.NewBranchReferenceName(testBranch)
	sourceHead, err := sourceRepo.Reference(branchRef, true)
	if err != nil {
		t.Fatalf("resolve source head: %v", err)
	}
	headCommit, err := sourceRepo.CommitObject(sourceHead.Hash())
	if err != nil {
		t.Fatalf("load head commit: %v", err)
	}
	markerHash := headCommit.ParentHashes[0]
	targetRepo := interruptedBootstrapTarget(t, sourceRepo, markerHash)

	sourceServer := newSmartHTTPRepoServerV2(t, sourceRepo)
	targetServer := newSmartHTTPRepoServer(t, targetRepo)
	targetServer.receivePackThinCap = true
	defer sourceServer.Close()
	defer targetServer.Close()

	tempRef := planner.BootstrapTempRef(branchRef)

	// Pack-carrying push: accept everything except the branch create, which the
	// target rejects per-ref (the shape --best-effort exists to tolerate).
	targetServer.receivePackHook = func(req *packp.UpdateRequests, hasPack bool) *packp.ReportStatus {
		if !hasPack {
			return nil // let ref-only pushes (the marker delete) apply for real
		}
		report := &packp.ReportStatus{UnpackStatus: "ok"}
		for _, cmd := range req.Commands {
			status := "ok"
			if cmd.Name == branchRef {
				status = "ng rejected by policy"
			} else if err := targetRepo.Storer.SetReference(plumbing.NewHashReference(cmd.Name, cmd.New)); err != nil {
				status = "ng " + err.Error()
			}
			report.CommandStatuses = append(report.CommandStatuses, &packp.CommandStatus{
				ReferenceName: cmd.Name, Status: status,
			})
		}
		return report
	}

	result, err := Run(context.Background(), Config{
		Source:       Endpoint{URL: sourceServer.RepoURL()},
		Target:       Endpoint{URL: targetServer.RepoURL()},
		Mode:         modeReplicate,
		AllRefs:      true,
		IncludeTags:  true,
		Prune:        true,
		BestEffort:   true,
		ProtocolMode: protocolModeAuto,
	})
	t.Logf("run result: relayMode=%q relayReason=%q err=%v", result.RelayMode, result.RelayReason, err)

	_, branchErr := targetRepo.Reference(branchRef, true)
	markerRefAfter, markerErr := targetRepo.Reference(tempRef, true)
	t.Logf("after run: branch present=%v, marker present=%v", branchErr == nil, markerErr == nil)
	if markerErr == nil {
		t.Logf("marker still at %s", markerRefAfter.Hash())
	}
	if branchErr != nil && markerErr != nil {
		t.Fatalf("RESUME STATE LOST: branch %s absent AND marker %s deleted", branchRef, tempRef)
	}
	_ = git.ErrBranchExists
}
